// CustodyLineNarrow answers with `p` and everything else that narrows a
// read of a CustodyLine, which is whatever `scope` says.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func CustodyLineNarrow(ctx context.Context, scope Scope, p predicate.CustodyLine) (predicate.CustodyLine, error) {
	ps := make([]predicate.CustodyLine, 0, 2)
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.CustodyLineScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return custodyline.And(ps...), nil
	}
}

// narrow is [CustodyLineNarrow] with this server's own scope.
func (s CustodyLineServiceServer) narrow(ctx context.Context, p predicate.CustodyLine) (predicate.CustodyLine, error) {
	return CustodyLineNarrow(ctx, s.Scope, p)
}

