func CustodyLineSelect(q *ent.CustodyLineQuery, m *loft.CustodyLineSelect) {
	if !m.GetAll() {
		fields := CustodyLineSelectedFields(m)
		q.Select(fields...)
	}
	if m.HasTenant() {
		q.WithTenant(func(q *ent.TenantQuery) {
			TenantSelect(q, m.GetTenant())
		})
	}
	if m.HasCustody() {
		q.WithCustody(func(q *ent.CustodyQuery) {
			q.Where(custody.DateErasedIsNil())
			CustodySelect(q, m.GetCustody())
		})
	}
	if m.HasAsset() {
		q.WithAsset(func(q *ent.AssetQuery) {
			q.Where(asset.DateErasedIsNil())
			AssetSelect(q, m.GetAsset())
		})
	}
	if m.HasStock() {
		q.WithStock(func(q *ent.StockQuery) {
			q.Where(stock.DateErasedIsNil())
			StockSelect(q, m.GetStock())
		})
	}
}

